import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Auth middleware - checks HMAC signature
app.use((req, res, next) => {
  const sig = req.headers['x-api-signature'];
  const ts = req.headers['x-timestamp'];
  if (!sig || !ts) return res.status(401).json({ error: 'missing auth' });
  const payload = `${req.method}:${req.path}:${ts}:${JSON.stringify(req.body)}`;
  const expected = crypto.createHmac('sha256', process.env.API_SECRET || 'dev-key')
    .update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(403).json({ error: 'invalid signature' });
  }
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, min_price, max_price, sort_by, order } = req.query;

    // Build base query
    let query = 'SELECT id, name, category, price, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      // Category uses parameterized query
      query += ` AND category = $${paramIdx++}`;
      params.push(category);
    }

    if (min_price) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(min_price));
    }

    if (max_price) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(max_price));
    }

    // Sort - validated against allowlist... partially
    const allowedSorts = ['price', 'name', 'stock_count', 'created_at'];
    const sortField = sort_by || 'name';
    const sortOrder = (order || 'asc').toLowerCase();

    if (allowedSorts.includes(sortField)) {
      query += ` ORDER BY ${sortField} ${sortOrder}`;
    }

    query += ' LIMIT 50';

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk lookup by IDs
app.post('/api/v2/products/bulk', async (req, res) => {
  try {
    const { ids, fields } = req.body;

    if (!Array.isArray(ids) || ids.length === 0 || ids.length > 100) {
      return res.status(400).json({ error: 'ids must be array of 1-100 elements' });
    }

    // Validate fields requested
    const safeFields = ['id', 'name', 'category', 'price', 'stock_count', 'description'];
    const selectedFields = (fields || ['id', 'name', 'price'])
      .filter(f => safeFields.includes(f))
      .join(', ');

    // Build IN clause - ids are cast to integers for safety
    const placeholders = ids.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT ${selectedFields} FROM products WHERE id IN (${placeholders})`;

    const result = await pool.query(query, ids.map(id => parseInt(id, 10)));
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Bulk lookup error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Report endpoint - generates CSV export
app.get('/api/v2/reports/inventory', async (req, res) => {
  try {
    const { warehouse, format_spec } = req.query;

    // format_spec allows custom column ordering for CSV export
    const baseQuery = `SELECT * FROM inventory_view WHERE warehouse_id = $1`;
    let query = baseQuery;

    if (format_spec) {
      // format_spec is a comma-separated list of column expressions
      query = `SELECT ${format_spec} FROM inventory_view WHERE warehouse_id = $1`;
    }

    const result = await pool.query(query, [warehouse]);

    if (req.headers['accept'] === 'text/csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Report error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Inventory API running on :3000'));
